export class ImageTray{constructor(){this.onDelete=null,this.items=[],this.el=document.createElement("div"),this.el.className="sn-image-tray",this.el.hidden=!0;const t=document.createElement("div");t.className="sn-tray-header",t.textContent="Images",this.listEl=document.createElement("div"),this.listEl.className="sn-tray-list",this.el.appendChild(t),this.el.appendChild(this.listEl)}add(t,s,n){this.items.some(e=>e.src===t)||(this.items.push({src:t,alt:s,filename:n}),this.el.hidden=!1,this._renderItem(t,s,n))}_renderItem(t,s,n){const e=document.createElement("div");e.className="sn-tray-item",e.draggable=!0,e.dataset.src=t,e.dataset.alt=s,e.title=n;const i=document.createElement("img");i.src=t,i.alt=s,i.className="sn-tray-thumb";const d=document.createElement("span");d.className="sn-tray-label",d.textContent=n;const a=document.createElement("button");a.type="button",a.className="sn-tray-delete",a.innerHTML="&times;",a.title="Remove",a.addEventListener("click",l=>{l.stopPropagation();const c=this.items.findIndex(r=>r.src===t);c>=0&&this.items.splice(c,1),e.remove(),this.items.length===0&&(this.el.hidden=!0),this.onDelete?.(t)}),e.appendChild(i),e.appendChild(d),e.appendChild(a),e.addEventListener("dragstart",l=>{l.dataTransfer.effectAllowed="copy",l.dataTransfer.setData("application/x-snakk-img",JSON.stringify({src:t,alt:s}))}),this.listEl.appendChild(e)}}
